#!/usr/bin/env bash
# Creates the starter issues. Requires the GitHub CLI (https://cli.github.com) and `gh auth login`.
# Usage: ./scripts/create-issues.sh OWNER/REPO
set -euo pipefail
REPO="${1:?usage: create-issues.sh OWNER/REPO}"
for l in "wave:#10b981" "good first issue:#7057ff" "web:#0ea5e9" "sdk:#f59e0b" "contracts:#ef4444" "documentation:#64748b" "security:#dc2626" "accessibility:#14b8a6" "complexity: trivial:#bbf7d0" "complexity: medium:#fde68a" "complexity: high:#fecaca"; do
  gh label create "${l%%:#*}" --color "${l##*:#}" --repo "$REPO" 2>/dev/null || true
done
gh issue create --repo "$REPO" --title "[Web] Add a copy-address button to the header wallet chip" --label "good first issue,web,complexity: trivial" --body "Users should be able to copy their full Stellar address from the header.\n\n**Files**\n- `web/src/components/Header.tsx`\n\n**Acceptance criteria**\n- [ ] A copy icon button next to the truncated address copies the full address\n- [ ] A 'Copied' confirmation shows for 2 seconds\n- [ ] Accessible label and keyboard support\n\n**Complexity:** Trivial\n\n**Hint:** Use `navigator.clipboard.writeText` and the `Copy`/`Check` icons from `lucide-react`.\n"
gh issue create --repo "$REPO" --title "[Web] Add friendly empty states for no plans and no subscriptions" --label "good first issue,web,complexity: trivial" --body "The empty states are a single line of text. Make them helpful.\n\n**Files**\n- `web/src/components/PlanList.tsx`\n- `web/src/components/Subscriptions.tsx`\n\n**Acceptance criteria**\n- [ ] Each empty state has a small inline SVG, a one-line explanation and a call to action\n- [ ] Works at mobile width\n- [ ] No new dependencies\n\n**Complexity:** Trivial\n\n**Hint:** Keep the existing paper and ink styling.\n"
gh issue create --repo "$REPO" --title "[SDK] Add JSDoc and a usage example to every public method" --label "good first issue,sdk,documentation,complexity: trivial" --body "Public SDK methods have little documentation, which hurts editor tooltips.\n\n**Files**\n- `sdk/src/client.ts`\n- `sdk/src/types.ts`\n- `sdk/src/time.ts`\n\n**Acceptance criteria**\n- [ ] Every exported function, class and method has JSDoc with parameter descriptions\n- [ ] `createPlan`, `subscribe` and `charge` include an `@example`\n- [ ] `npm run build` passes\n\n**Complexity:** Trivial\n\n**Hint:** Describe units explicitly (base units, seconds).\n"
gh issue create --repo "$REPO" --title "[Docs] Write a guide to run the keeper on a small server" --label "good first issue,documentation,complexity: trivial" --body "Merchants need to run the keeper reliably. Document it.\n\n**Files**\n- `docs/KEEPER.md`\n\n**Acceptance criteria**\n- [ ] Step-by-step guide for a systemd service and for Docker\n- [ ] Explains required environment variables and how to fund the keeper account\n- [ ] Linked from README.md\n\n**Complexity:** Trivial\n\n**Hint:** The CLI is `npm run keeper`; see `sdk/src/keeper-cli.ts`.\n"
gh issue create --repo "$REPO" --title "[Contract] Add tests for multiple subscribers, plans and boundary values" --label "wave,contracts,complexity: medium" --body "Increase confidence in the due-date and accounting rules.\n\n**Files**\n- `contracts/src/lib.rs`\n\n**Acceptance criteria**\n- [ ] Test: two subscribers on one plan are charged independently\n- [ ] Test: one subscriber on two plans keeps separate schedules\n- [ ] Test: charging exactly at `next_charge` succeeds and one second earlier fails\n- [ ] Test: extremely large period values do not overflow\n- [ ] `cargo test` passes in CI\n\n**Complexity:** Medium\n\n**Hint:** Use `env.ledger().set_timestamp` to control time.\n"
gh issue create --repo "$REPO" --title "[SDK] Retry with backoff and clearer error handling" --label "wave,sdk,complexity: medium" --body "RPC calls fail transiently and errors can be cryptic.\n\n**Files**\n- `sdk/src/client.ts`\n\n**Acceptance criteria**\n- [ ] `sendTransaction` and reads retry on network errors with exponential backoff (configurable)\n- [ ] Allowance errors from the token contract are translated into a readable message\n- [ ] Unit tests with a stubbed RPC server prove retry behaviour\n\n**Complexity:** Medium\n\n**Hint:** Keep `describeError` as the single place that maps errors to messages.\n"
gh issue create --repo "$REPO" --title "[Web] Allowance manager: view, increase and revoke" --label "wave,web,complexity: medium" --body "Subscribers cannot see or change how much the contract may pull.\n\n**Files**\n- `web/src/components/`\n- `sdk/src/client.ts`\n\n**Acceptance criteria**\n- [ ] SDK exposes `getAllowance` and `revokeAllowance` (approve with 0)\n- [ ] The Subscriptions tab shows the remaining allowance per token and a warning when it would not cover the next charge\n- [ ] A button increases or revokes it\n- [ ] Mock implements the same methods with tests\n\n**Complexity:** Medium\n\n**Hint:** Token `allowance(from, spender)` is a read-only call.\n"
gh issue create --repo "$REPO" --title "[Web] Accessibility audit and reduced-motion support" --label "wave,web,accessibility,complexity: medium" --body "Make the app usable with keyboard and screen readers.\n\n**Files**\n- `web/src/`\n\n**Acceptance criteria**\n- [ ] All controls reachable and operable by keyboard with visible focus\n- [ ] Tabs follow the WAI-ARIA tabs pattern (arrow-key navigation)\n- [ ] Countdown text updates are not announced every second (use a throttled live region)\n- [ ] Contrast meets WCAG AA\n- [ ] Findings summarised in the PR\n\n**Complexity:** Medium\n\n**Hint:** Use axe DevTools or Lighthouse for a first pass.\n"
gh issue create --repo "$REPO" --title "[SDK] Keeper: concurrency limit, jitter and metrics output" --label "wave,sdk,complexity: medium" --body "The keeper charges sequentially and logs plain text only.\n\n**Files**\n- `sdk/src/keeper.ts`\n- `sdk/src/keeper-cli.ts`\n\n**Acceptance criteria**\n- [ ] Configurable concurrency for charging due subscriptions\n- [ ] Random jitter between runs\n- [ ] Optional JSON log lines and a final summary with counts and durations\n- [ ] Tests using `MockPayCycle`\n\n**Complexity:** Medium\n\n**Hint:** Avoid sending two transactions from one account with the same sequence number.\n"
gh issue create --repo "$REPO" --title "[Contract] Grace period and retry state for failed charges" --label "wave,contracts,complexity: high" --body "A failed charge (no allowance or balance) currently just reverts and nothing records it.\n\n**Files**\n- `contracts/src/lib.rs`\n- `sdk/src/mock.ts`\n\n**Acceptance criteria**\n- [ ] Subscription gains `past_due` state and `failed_attempts`\n- [ ] `charge` uses `try_transfer_from`; on failure it records the attempt instead of reverting\n- [ ] After a configurable number of failures the subscription is cancelled\n- [ ] Mock and SDK types updated, with contract and mock tests\n- [ ] Behaviour documented in `docs/ARCHITECTURE.md`\n\n**Complexity:** High\n\n**Hint:** The generated token client has `try_` variants that return a `Result`.\n"
gh issue create --repo "$REPO" --title "[Contract] Optional keeper tip paid by the merchant" --label "wave,contracts,security,complexity: high" --body "Third parties have no incentive to run keepers.\n\n**Files**\n- `contracts/src/lib.rs`\n- `sdk/src/`\n\n**Acceptance criteria**\n- [ ] Plan has an optional `keeper_tip` (base units, at most 5% of amount)\n- [ ] `charge` pays the tip to the caller out of the charged amount\n- [ ] Merchant receives `amount - tip`; tests cover rounding and caps\n- [ ] SDK and mock updated; docs describe the economics\n\n**Complexity:** High\n\n**Hint:** The tip must come out of the merchant's share so subscribers never pay more than the plan amount.\n"
gh issue create --repo "$REPO" --title "[Contract+SDK] Plan upgrade and downgrade with proration" --label "wave,contracts,sdk,complexity: high" --body "Subscribers cannot move between plans without cancelling and paying again.\n\n**Files**\n- `contracts/src/lib.rs`\n- `sdk/src/`\n- `web/src/`\n\n**Acceptance criteria**\n- [ ] `change_plan(sub_id, new_plan_id)` for plans with the same token and merchant\n- [ ] Unused time on the old period is credited against the new plan using integer maths\n- [ ] Property-style tests prove no overpayment or loss of funds\n- [ ] SDK, mock and a web UI control for switching\n- [ ] Design notes added to `docs/ARCHITECTURE.md`\n\n**Complexity:** High\n\n**Hint:** Decide how credits are represented without custodying funds, and document the choice in the PR.\n"
